package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/rooms/{roomId}/comments") public class RoomCommentController{private final RoomCommentService service;public RoomCommentController(RoomCommentService s){service=s;}@PostMapping public Mono<RoomCommentView> publish(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@Valid@RequestBody PublishRoomCommentRequest r){return service.publish(a,roomId,r);}@GetMapping public Flux<RoomCommentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId){return service.list(a,roomId);}@PutMapping("/{commentId}")public Mono<RoomCommentView> edit(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId,@Valid@RequestBody EditRoomCommentRequest r){return service.edit(a,commentId,r);}@DeleteMapping("/{commentId}")public Mono<RoomCommentView> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId){return service.delete(a,commentId);}}
